C.heroPowerBehaviors=[...new Set(Object.values(C.heroPowers||{}).map(x=>x&&x.behavior).filter(Boolean))];
C.heroShop=Object.fromEntries(Object.entries(C.heroShopPrices||{}).map(([id,coins])=>[id,{coins}]));
C.bossIds=C.bossDefinitions.map(b=>b.id);
C.bosses=C.bossDefinitions.map(({id,schedule,patterns,tip,profileOrder,profileName,...b})=>b);
C.bossSchedule=C.bossDefinitions.map(b=>b.schedule);
C.bossPatterns=C.bossDefinitions.map(b=>b.patterns);
C.bossTips=C.bossDefinitions.map(b=>b.tip);
C.profileBossIds=C.bossDefinitions.slice().sort((a,b)=>(a.profileOrder??999)-(b.profileOrder??999)).map(b=>[b.id,b.profileName||b.name]);
C.profileEnemyIds=Object.entries(C.demons).filter(([,d])=>Number.isFinite(d.profileOrder)&&d.profileName).sort((a,b)=>a[1].profileOrder-b[1].profileOrder).map(([id,d])=>[id,d.profileName]);
C.demonDefinitions=Object.fromEntries(Object.entries(C.demons).map(([id,d])=>[id,{id,...d,palette:C.demonPalettes[id]||null,library:C.demonInfo[id]||null,libraryTip:C.libraryTips[id]||''}]));
function validate(){
 const C=global.FE_SURVIVOR_CONTENT, errors=[], has=(o,k)=>!!o&&Object.prototype.hasOwnProperty.call(o,k);
 for(const [id,h] of Object.entries(C.heroes||{})){if(!C.heroProfiles[id])errors.push('Hero '+id+' has no profile.');if(h.start&&!C.weapons[h.start])errors.push('Hero '+id+' starts with missing weapon '+h.start+'.');if(!Number.isFinite(C.heroAttackRange[id]))errors.push('Hero '+id+' has no attack range.');if(id!=='mendigo'&&!C.heroPowers[id])errors.push('Hero '+id+' has no Heroic Power.');if(C.heroPowers[id]&&!C.heroPowerBehaviors.includes(C.heroPowers[id].behavior))errors.push('Hero '+id+' has unsupported Heroic Power behavior.');}
 for(const id of Object.keys(C.heroProfiles||{}))if(!C.heroes[id])errors.push('Hero profile '+id+' has no base hero entry.');
 for(const [group,entries] of [['weapon',C.weapons],['passive',C.passives],['active',C.actives]])for(const [id,entry] of Object.entries(entries||{})){if(!(group==='active'?entry.n:entry.name))errors.push(group+' '+id+' has no display name.');if(!C.categories[id])errors.push(group+' '+id+' has no category.');}
 if(!C.weapons.sling)errors.push('The sling tree has no base weapon (sling).');
 for(const id of Object.keys(C.demons||{}))if(!C.demonInfo[id])errors.push('Demon '+id+' has no Library description.');for(const id of Object.keys(C.demonInfo||{}))if(!C.demons[id])errors.push('Demon info '+id+' has no enemy definition.');
 if(C.bossDefinitions.length!==C.bossSchedule.length||C.bossDefinitions.length!==C.bossPatterns.length||C.bossDefinitions.length!==C.bossTips.length||C.bossDefinitions.length!==C.bossIds.length)errors.push('Boss compatibility arrays do not match the canonical boss catalog.');
 for(const id of Object.keys(C.categories||{}))if(!C.weapons[id]&&!C.passives[id]&&!C.actives[id])errors.push('Category '+id+' has no matching content.');
 for(const [group,entries] of Object.entries(C.evolutionTrees||{})){const source=group==='weapon'?C.weapons:group==='passive'?C.passives:C.actives;for(const id of Object.keys(entries))if(!source[id])errors.push('Evolution tree '+group+'.'+id+' has no matching content.');}
 for(const [id,name] of C.profileEnemyIds)if(!C.demons[id])errors.push('Profile enemy '+id+' ('+name+') has no enemy definition.');for(const [id,name] of C.profileBossIds)if(!C.bossIds.includes(id))errors.push('Profile boss '+id+' ('+name+') has no boss ID.');
 for(const [id,entry] of Object.entries(C.weapons||{})){const contract=C.weaponBehaviorContracts[entry&&entry.behavior];if(!contract)errors.push('Weapon '+id+' has unsupported behavior '+String(entry&&entry.behavior)+'.');else for(const field of contract.requiredBase)if(!has(entry.base||{},field))errors.push('Weapon '+id+' is missing base.'+field+'.');if(entry&&entry.behavior==='melee_arc'&&!['sword','jawbone'].includes(entry.variant))errors.push('Weapon '+id+' melee_arc requires variant sword or jawbone.');}
 for(const [id,entry] of Object.entries(C.passives||{})){if(!C.passiveBehaviorContracts[entry&&entry.behavior])errors.push('Passive '+id+' has unsupported behavior.');const max=Number(entry.maxLevel??5),weight=Number(entry.pickWeight??1);if(!Number.isInteger(max)||max<1||max>5)errors.push('Passive '+id+' has invalid maxLevel.');if(!Number.isFinite(weight)||weight<=0||weight>1.5)errors.push('Passive '+id+' has invalid pickWeight.');}for(const [id,entry] of Object.entries(C.actives||{}))if(!C.activeBehaviorContracts[entry&&entry.behavior])errors.push('Active '+id+' has unsupported behavior.');
 for(const [id,entry] of Object.entries(C.demons||{})){if(!C.demonSpawnPools.includes(entry.spawnPool))errors.push('Demon '+id+' has invalid spawnPool.');if(!C.demonMovementBehaviors.includes(entry.mv))errors.push('Demon '+id+' has unsupported movement.');if(entry.ab&&!C.demonAbilityBehaviors.includes(entry.ab))errors.push('Demon '+id+' has unsupported ability.');if(!entry.spr)errors.push('Demon '+id+' has no sprite key.');if(entry.artTemplate&&!C.demonArtTemplates.includes(entry.artTemplate))errors.push('Demon '+id+' has unsupported artTemplate.');if(entry.spawnPool==='survival'&&(!(Number(entry.w)>0)||!Number.isFinite(entry.from)))errors.push('Survival demon '+id+' must define a positive weight and a finite start time.');if(entry.rangedAttack){const attack=entry.rangedAttack,contract=C.demonBehaviorContracts[attack.behavior];if(!contract)errors.push('Demon '+id+' has unsupported ranged attack.');else for(const field of contract.required)if(!has(attack,field))errors.push('Demon '+id+' rangedAttack is missing '+field+'.');}}
 for(const [id,weapon] of Object.entries(C.weapons||{}))for(const [index,upgrade] of (weapon.up||[]).entries()){if(!Array.isArray(upgrade.ops))errors.push('Weapon '+id+' upgrade '+index+' has no serializable ops.');else for(const op of upgrade.ops){if(!op||(!has(weapon.base||{},op.key)&&op.op!=='set'))errors.push('Weapon '+id+' upgrade '+index+' targets unknown base stat.');if(!op||!C.statOperationContracts.includes(op.op))errors.push('Weapon '+id+' upgrade '+index+' has unsupported operation.');if(!op||!(typeof op.value==='boolean'||Number.isFinite(op.value)))errors.push('Weapon '+id+' upgrade '+index+' has invalid operation value.');}}
 for(const [id,profile] of Object.entries(C.heroProfiles||{})){if(profile.grace&&!C.heroEffectBehaviorContracts[profile.grace.effect&&profile.grace.effect.behavior])errors.push('Hero '+id+' has unsupported grace effect.');for(const [index,perk] of (profile.perks||[]).entries()){const effect=perk&&perk[2];if(!effect||!C.heroEffectBehaviorContracts[effect.behavior])errors.push('Hero '+id+' mastery '+index+' has unsupported effect.');else for(const field of C.heroEffectBehaviorContracts[effect.behavior].required||[])if(!has(effect,field))errors.push('Hero '+id+' mastery '+index+' is missing effect.'+field+'.');}}
 if(Object.keys(C.heroShop||{}).some(id=>!C.heroes[id]))errors.push('Hero shop contains an unknown hero.');if(C.bossDefinitions.some((b,i)=>!b.id||!b.name||!b.spr||!Number.isFinite(b.schedule)||!Array.isArray(b.patterns)||!b.tip||C.bosses[i].name!==b.name||b.id!==C.bossIds[i]||b.patterns!==C.bossPatterns[i]||b.schedule!==C.bossSchedule[i]))errors.push('Canonical boss entry is incomplete or compatibility arrays are not aligned.');for(const boss of C.bossDefinitions)for(const pattern of boss.patterns)if(!has(C.bossPatternNames,pattern))errors.push('Boss '+boss.id+' uses unknown pattern '+pattern+'.');
 for(const [id,e] of Object.entries(C.supremeEvolutions||{})){if(!C.weapons[id]&&!C.passives[id]&&!C.actives[id])errors.push('Supreme evolution '+id+' has no matching content.');if(!C.passives[e.dom])errors.push('Supreme evolution '+id+' has an invalid dom passive.');if(!e.n||!e.d||!e.ref)errors.push('Supreme evolution '+id+' is missing name, reference or description.');for(const op of e.ops||[])if(!op.key||!(C.statOperationContracts||[]).includes(op.op))errors.push('Supreme evolution '+id+' has an invalid stat operation.');}
 {const ids=new Set(),A=C.achievements||{};for(const a of (A.entries||[])){if(!a.id||!a.name||!a.desc||!Number.isFinite(a.reward))errors.push('Achievement '+(a.id||'?')+' is incomplete.');if(ids.has(a.id))errors.push('Duplicate achievement '+a.id+'.');ids.add(a.id);}for(const id of Object.keys(A.sections||{}))if(!ids.has(id))errors.push('Achievement section '+id+' has no matching achievement.');}
 for(const [i,w] of (C.worlds||[]).entries())if(!w.n||!['hp','spd','spawn','coin'].every(k=>Number.isFinite(w[k])))errors.push('World '+i+' is incomplete.');
 if(!C.masteryTiers||C.masteryTiers.thresholds.length!==C.masteryTiers.labels.length)errors.push('Mastery tiers and labels must have the same length.');
 {const EA=C.enemyAnimation;if(!EA)errors.push('Missing enemyAnimation.');else{for(const [id,arch] of Object.entries(EA.archetypes))if(!C.demons[id]||!EA.states[arch])errors.push('Enemy animation '+id+' has an invalid demon or archetype.');for(const [arch,st] of Object.entries(EA.states))if(st.idle.length!==6||st.hurt.length!==2||st.death.length!==4||!st.lunge)errors.push('Enemy animation archetype '+arch+' needs 6 idle, 2 hurt, 4 death frames and a lunge.');for(const id of Object.keys(C.demons))if(!(EA.handDrawn||[]).includes(id)&&!EA.archetypes[id])errors.push('Demon '+id+' has no animation archetype.');}}
 for(const id of Object.keys(C.heroPowerTuning||{}))if(!C.heroPowerBehaviors.includes(id))errors.push('Hero power tuning '+id+' has no matching hero power.');
 for(const id of Object.keys(C.weaponTuning||{}))if(!C.weapons[id])errors.push('Weapon tuning '+id+' has no matching weapon.');
 for(const k of ['news','worlds','endTips','demonAbilityText','masteryTiers','achievements','supremeEvolutions','weaponTuning','heroPowerTuning','enemyAnimation'])if(!C[k])errors.push('Missing registry section: '+k+'.');
 if(C.weapons.whip&&!(C.weaponTuning||{}).whip)errors.push('Weapon whip needs weaponTuning.whip.');
 if(Object.values(C.heroPowers||{}).some(p=>p&&p.behavior==='jericho_march')&&!(C.heroPowerTuning||{}).jericho_march)errors.push('Hero power jericho_march needs heroPowerTuning.jericho_march.');
 return errors;
}
C.validate=validate;
global.FE_SURVIVOR_CONTENT=C;
